/* Panel de contenido de MSG-01 · Lista de Hilos.
   Ningún color literal: todo sale de los tokens de design-system.md §1.
   Nota de tokens: la paleta no define un blanco puro, así que los controles usan
   --bw-surface-mist (superficie clara de §1.4) y el texto sobre azul usa
   --bw-cold-white. */

.panel {
  padding: 24px 28px 40px;
  background: var(--bw-cold-white);
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-hint);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.sub {
  max-width: 560px;
  margin: 0 0 16px;
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Barra de acciones ───────────────────────────────────────────────────── */

.actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.search {
  flex: 1;
  max-width: 300px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
}

.search:focus {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.search::placeholder {
  color: var(--bw-input-placeholder);
}

.primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
}

.primary:disabled {
  background: var(--bw-hint-steel);
  cursor: not-allowed;
}

.scope {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.count {
  margin-left: auto;
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

/* ── Aviso de error ──────────────────────────────────────────────────────── */

.error {
  margin-bottom: 14px;
  padding: 8px 10px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: var(--bw-size-label);
  line-height: 1.5;
  word-break: break-word;
}

.loading {
  margin: 0;
  padding: 18px 0;
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

/* ── Paginación ──────────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius-hamburger);
  background: var(--bw-surface-mist);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}

.pageBtn:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.pageCtrl {
  color: var(--bw-input-placeholder);
}

.pageActive,
.pageActive:hover:not(:disabled) {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

