import { useEffect, useState } from 'react';

import { fetchThreadPage, pageCount, type ThreadSummary } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';

import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — la pantalla, no un componente de presentación.
 *
 * Es dueña del estado de búsqueda y de página, y es la única que toca red:
 * llama a `fetchThreadPage` con el `orgId` del perfil. La fila la pinta
 * `ThreadList`, que no sabe de dónde vienen los datos.
 */
interface Props {
  profile: MemberProfile;
  /**
   * Inyectable para que los tests no dependan del reloj. Viaja tal cual hasta
   * `relativeTime`, que ya tiene su propio `new Date()` de respaldo: por eso el
   * tipo es `Date | undefined` y no `Date` (F-137).
   */
  now?: Date | undefined;
  /**
   * Firma pública de la pantalla congelada por F-118: el shell la pasa desde
   * `App.tsx`. Se recibe y se ignora a propósito — MSG-02 no existe todavía, así
   * que abrir un hilo no lleva a ninguna parte y la pantalla no la cablea.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * El detalle del fallo, en texto, para el aviso (F-020 · F-128).
 *
 * Lo que rechaza PostgREST no es un `Error`: es un objeto plano `{ code, message }`,
 * así que `String(e)` daría `[object Object]` y `e.message` daría `undefined` — la
 * pantalla se comería el `PGRST201` que explica el fallo entero. Se sacan `code`
 * y `message` cuando existan, y cuando no haya nada legible se devuelve cadena
 * vacía en vez de un `[object Object]` en rojo.
 */
function errorDetail(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === 'string') return e;
  if (typeof e === 'object' && e !== null) {
    const candidate = e as { code?: unknown; message?: unknown };
    const parts: string[] = [];
    if (typeof candidate.code === 'string' && candidate.code !== '') parts.push(candidate.code);
    if (typeof candidate.message === 'string' && candidate.message !== '') parts.push(candidate.message);
    return parts.join(' · ');
  }
  return '';
}

export function Messages({ profile, now }: Props) {
  const { orgId } = profile;

  /** Lo que hay escrito en el input. */
  const [term, setTerm] = useState('');
  /** Lo que se ha buscado de verdad (al pulsar Enter). */
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const [threads, setThreads] = useState<ThreadSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId, search, page })
      .then((res) => {
        if (!alive) return;
        setThreads(res.threads);
        setTotal(res.total);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        const detail = errorDetail(e);
        setError(
          detail ? `No se pudieron cargar los hilos. ${detail}` : 'No se pudieron cargar los hilos.',
        );
      })
      .finally(() => {
        if (!alive) return;
        setLoading(false);
      });
    return () => {
      alive = false;
    };
  }, [orgId, search, page]);

  const pages = pageCount(total);
  const pageNumbers = Array.from({ length: pages }, (_, i) => i + 1);

  /** MSG-02 no está en el alcance: la fila se puede pulsar y no lleva a ningún sitio. */
  const handleOpen = () => {
    /* intencionadamente vacío */
  };

  return (
    <div className={styles.panel}>
      <div className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</div>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.sub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.actions}>
        <input
          type="text"
          className={styles.search}
          placeholder="Buscar por nombre de organización..."
          aria-label="Buscar por nombre de organización"
          value={term}
          onChange={(e) => setTerm(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              setSearch(term);
              setPage(1);
            }
          }}
        />
        {/* Deshabilitado con el motivo al lado: DIR-01 no está entre las 8 pantallas
            del alcance. El motivo vive en su propio nodo, no dentro del botón. */}
        <button type="button" className={styles.primary} disabled>
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.scope} data-testid="directorio-scope">
          El Directorio (DIR-01) queda fuera del MVP: este botón no lleva a ninguna parte.
        </span>
        <span className={styles.count} data-testid="pag-info">
          {`${total} hilos · Página ${page} de ${pages}`}
        </span>
      </div>

      {error ? (
        /* `alert` no sale gratis del HTML: hay que escribirlo. El estado vacío y el
           de carga no lo llevan — es para lo que interrumpe. */
        <div className={styles.error} role="alert">
          {error}
        </div>
      ) : null}

      {loading ? (
        <p className={styles.loading}>Cargando hilos…</p>
      ) : (
        <ThreadList threads={threads} now={now} onOpen={handleOpen} />
      )}

      <nav className={styles.pagination} aria-label="Paginación de hilos">
        <button
          type="button"
          className={`${styles.pageBtn} ${styles.pageCtrl}`}
          aria-label="Página anterior"
          disabled={page <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          <span aria-hidden="true">‹</span>
        </button>
        {pageNumbers.map((n) => (
          <button
            key={n}
            type="button"
            /* El número va como TEXTO y sin `aria-label`: un aria-label sustituye el
               nombre accesible y el botón dejaría de llamarse "2" (F-145). */
            className={`${styles.pageBtn}${n === page ? ` ${styles.pageActive}` : ''}`}
            aria-current={n === page ? 'page' : undefined}
            onClick={() => setPage(n)}
          >
            {n}
          </button>
        ))}
        <button
          type="button"
          className={`${styles.pageBtn} ${styles.pageCtrl}`}
          aria-label="Página siguiente"
          disabled={page >= pages}
          onClick={() => setPage((p) => Math.min(pages, p + 1))}
        >
          <span aria-hidden="true">›</span>
        </button>
      </nav>
    </div>
  );
}

