/* Lista de hilos de MSG-01.
   Ningún color literal: todo sale de los tokens de design-system.md §1.
   Nota de token: la paleta no tiene un blanco puro, así que la superficie de la
   tarjeta usa --bw-surface-mist, el neutro de superficie más claro de §1.4. */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: hidden;
}

/* El rol `listitem` vive aquí y no se pisa con ningún `role` explícito. */
.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}

.row:last-child {
  border-bottom: none;
}

.rowBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  border-radius: 0;
  font-family: var(--bw-font-body);
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}

.rowBtn:hover {
  background: var(--bw-row-hover-tint);
}

.rowBtn:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.org {
  font-size: var(--bw-size-eyebrow);
  font-weight: 500;
  color: var(--bw-deep-steel);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  white-space: nowrap;
  justify-self: end;
}

.bottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Un tono por valor de `StateTone`. */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ── Estado vacío ────────────────────────────────────────────────────────────
   Contenedor propio, nunca un `<li>` dentro de la `<ul>` de arriba. */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 40px 18px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  text-align: center;
}

.emptyText {
  margin: 0;
  max-width: 520px;
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-deep-steel);
}

.emptyBtn {
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
}

.emptyBtn:disabled {
  background: var(--bw-hint-steel);
  cursor: not-allowed;
}

.emptyReason {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

