import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01.
 *
 * Presentacional y nada más: pinta las filas en el orden que las recibe (el
 * orden es del servidor, `last_item_at` descendente) y avisa con el ID del hilo
 * cuando se abre una. No carga datos ni pagina — eso es de `Messages.tsx`.
 *
 * Tres cosas de forma que aquí no son cosmética:
 *
 * 1. La fila es un `<li>` con un `<button>` DENTRO (F-131). Un `role` explícito
 *    no se suma al implícito, lo sustituye: `<li role="button">` deja de ser
 *    `listitem`, y el contrato consulta ese rol nueve veces. Y poner los dos
 *    tampoco vale: el `<li>` pasaría a ser un segundo botón con el mismo nombre
 *    accesible que el de dentro y `getByRole('button', { name: /…/ })` fallaría
 *    por encontrar dos. Igual con el `<ul>`: es `list` y no se pisa.
 *
 * 2. El estado vacío va en un `<div>` FUERA de cualquier `<ul>` (F-141), porque
 *    el contrato exige que con `threads` vacío no quede ningún `listitem` en el
 *    documento.
 *
 * 3. El diccionario tono→clase es `Record<StateTone, string | undefined>`
 *    (F-143). Con `noUncheckedIndexedAccess`, una propiedad de un CSS Module es
 *    `string | undefined`, y un `Record<StateTone, string>` a secas no compila:
 *    cinco `TS2322`, uno por valor de `StateTone`.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

interface Props {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /** Avisa con el ID del hilo, nunca con el objeto. */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: Props) {
  if (threads.length === 0) {
    return (
      /* El estado vacío NO va dentro de un `<ul>`: sin listas no hay listitem. */
      <div className={styles.empty}>
        {/* La frase va entera y en un solo nodo de texto, con sus tildes: partirla
            en título y cuerpo deja al `getByText` del contrato sin nada que leer. */}
        <p className={styles.emptyText}>
          {'Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.'}
        </p>
        {/* Deshabilitado y con el motivo visible: es la regla de §7 — un botón que
            parece pulsable y no lleva a ningún sitio. */}
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <span className={styles.emptyReason}>{'El Directorio (DIR-01) queda fuera del MVP.'}</span>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => (
        <li key={thread.id} className={styles.row}>
          <button type="button" className={styles.rowBtn} onClick={() => onOpen(thread.id)}>
            <span className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.country}>{thread.counterpartyCountry}</span>
              ) : null}
            </span>
            <span className={styles.ts}>{relativeTime(thread.lastItemAt, now)}</span>
            <span className={styles.bottom}>
              {/* Metadatos en claro, nunca contenido descifrado (spec §7). */}
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLASS[stateTone(thread.state)] ?? ''}`}>
                {thread.state}
              </span>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}
